package com.dyapp

import uniffi.dyapp.MobileDeviceDirectory
import uniffi.dyapp.MobileDeviceReadState
import uniffi.dyapp.MobileDeviceRowSource
import uniffi.dyapp.MobileDeviceSnapshot
import uniffi.dyapp.MobileOwnDevice

/** Freeze public display/target bytes; generated byte-array records are mutable at the UI boundary. */
internal class DeviceDirectoryRow(device: MobileOwnDevice) {
    private val target = device.key.copyOf()
    val current = device.current
    val identifier = target.joinToString("") { "%02x".format(it) }
    fun key(): ByteArray = target.copyOf()
}

internal class DeviceDirectoryListing(snapshot: MobileDeviceSnapshot) {
    val rows = snapshot.devices.map(::DeviceDirectoryRow)
    val state: MobileDeviceReadState = snapshot.state
    val source: MobileDeviceRowSource = snapshot.source
}

/** Reference identity owns one explicit confirmation, even when another opening has equal contents. */
internal class DeviceDisconnectOpening(val target: DeviceDirectoryRow)
internal class DeviceDisconnectCompletion(val target: DeviceDirectoryRow, val result: Result<Unit>)
internal enum class DeviceDirectoryOperation {
    CACHED,
    REFRESH,
    REVOKE
}

internal data class DeviceDirectoryViewState(
    val listing: DeviceDirectoryListing? = null,
    val operation: DeviceDirectoryOperation? = null,
    val retired: Boolean = false,
    val confirmation: DeviceDisconnectOpening? = null,
    val completion: DeviceDisconnectCompletion? = null,
    val failure: Throwable? = null
) {
    val busy: Boolean get() = operation != null
}

internal class DeviceDirectoryCalls(
    val read: (Boolean) -> MobileDeviceSnapshot,
    val revoke: (ByteArray) -> Unit,
    val close: () -> Unit
)

/** Construct off the UI thread; existing credentials only, never bootstrap or replace secrets. */
internal fun nativeDeviceDirectoryCalls(opened: Opened.Ready): DeviceDirectoryCalls {
    val directory = MobileDeviceDirectory(
        opened.slot.owner(),
        opened.slot.id,
        opened.peerId,
        PlatformKeyStore.existing(identityAlias(opened.slot.id))
    )
    return DeviceDirectoryCalls(directory::snapshot, directory::revoke, directory::close)
}
